<template>
	<view class="order-card" @click="handleCardClick">
		<!-- 订单头部 -->
		<view class="card-header">
			<view class="user-info">
				<image class="avatar" :src="orderData.userAvatar" mode="aspectFill"></image>
				<view class="user-details">
					<text class="username">{{ orderData.userName }} {{ orderData.userAge }}岁 {{ orderData.userGender }}</text>
					<text class="service-type">{{ orderData.serviceType }}</text>
				</view>
			</view>
			<view class="price">¥{{ orderData.price }}</view>
		</view>
		
		<!-- 服务信息 -->
		<view class="service-info">
			<view class="info-row">
				<text class="info-icon">🏥</text>
				<text class="info-text">{{ orderData.hospitalName || orderData.hospital }}</text>
				<text class="distance" v-if="orderData.distance">{{ orderData.distance }}</text>
			</view>
			
			<view class="info-row">
				<text class="info-icon">🕐</text>
				<text class="info-text">{{ orderData.appointmentTime }}</text>
			</view>
			
			<view class="info-row" v-if="orderData.duration">
				<text class="info-icon">⏱️</text>
				<text class="info-text">服务时长：{{ orderData.duration }}</text>
			</view>
			
			<view class="info-row">
				<text class="info-icon">📋</text>
				<text class="info-text">{{ orderData.serviceDetail }}</text>
			</view>
		</view>
		
		<!-- 特殊需求 -->
		<view class="special-needs" v-if="orderData.specialNote">
			<text class="needs-icon">ℹ️</text>
			<text class="needs-text">特殊需求：{{ orderData.specialNote }}</text>
		</view>
		
		<!-- 订单状态标签 -->
		<view class="status-tag" :class="statusClass" v-if="showStatus">
			<text>{{ statusText }}</text>
		</view>
		
		<!-- 操作按钮 -->
		<view class="card-actions" v-if="showActions">
			<button class="action-btn secondary" @click.stop="handleContact">📞 联系患者</button>
			<button class="action-btn primary" @click.stop="handleMainAction">❤️ {{ mainActionText }}</button>
		</view>
	</view>
</template>

<script setup>
import { computed, defineProps, defineEmits } from 'vue'

// 定义props
const props = defineProps({
	orderData: {
		type: Object,
		required: true
	},
	showActions: {
		type: Boolean,
		default: true
	},
	showStatus: {
		type: Boolean,
		default: false
	},
	actionType: {
		type: String,
		default: 'accept' // accept, start, complete, view
	}
})

// 定义emits
const emit = defineEmits(['card-click', 'contact', 'main-action'])

// 计算属性
const statusClass = computed(() => {
	const statusMap = {
		pending: 'status-pending',
		accepted: 'status-accepted',
		in_progress: 'status-progress',
		completed: 'status-completed',
		cancelled: 'status-cancelled'
	}
	return statusMap[props.orderData.status] || 'status-pending'
})

const statusText = computed(() => {
	const statusMap = {
		pending: '待接单',
		accepted: '已接单',
		in_progress: '进行中',
		completed: '已完成',
		cancelled: '已取消'
	}
	return statusMap[props.orderData.status] || '待接单'
})

const mainActionText = computed(() => {
	const actionMap = {
		accept: '接单',
		start: '开始服务',
		complete: '完成服务',
		view: '查看详情'
	}
	return actionMap[props.actionType] || '接单'
})

// 方法定义
// 卡片点击
const handleCardClick = () => {
	emit('card-click', props.orderData)
}

// 联系患者
const handleContact = () => {
	emit('contact', props.orderData)
}

// 主要操作
const handleMainAction = () => {
	emit('main-action', {
		type: props.actionType,
		data: props.orderData
	})
}
</script>

